from itertools import combinations

def find_golomb_ruler(n):
    for i in range(1, 1000):
        ruler = [0, i]
        for j in range(2, n):
            for k in range(ruler[-1] + 1, 1000):
                distances = set()
                for pair in combinations(ruler + [k], 2):
                    distances.add(abs(pair[0] - pair[1]))
                if len(distances) == len(ruler) + 1:
                    ruler.append(k)
                    break
            else:
                break
        else:
            return ruler
    return "UNSATISFIABLE"

