def find_golomb_ruler(n):
    for i in range(1, 100):
        for marks in combinations(range(i), n):
            distances = set()
            for a, b in combinations(marks, 2):
                distances.add(abs(a - b))
            if len(distances) == n * (n - 1) // 2:
                return sorted(marks)
    return None

