from itertools import combinations

N = 8

# Generate all possible edges
edges = list(combinations(range(N), 2))

# Initialize an empty graph
graph = []

# Iterate over all possible edges
for edge in edges:
    # Add the edge to the graph if it doesn't create a cycle of length 3 or 4
    if not has_cycle(graph + [edge], N, 3) and not has_cycle(graph + [edge], N, 4):
        graph.append(edge)

    # If every vertex has degree 4, break the loop
    if all(degree(graph, v) == 4 for v in range(N)):
        break

# Check if every vertex has degree between 4 and 4
if all(4 = degree(graph, v) = 4 for v in range(N)):
    print(graph)
else:
    print("UNSATISFIABLE")

# Helper function to check if a graph has a cycle of a given length
def has_cycle(graph, N, length):
    # Iterate over all possible paths of the given length
    for path in get_paths(graph, length):
        # If the path is a cycle, return True
        if path[0] == path[-1]:
            return True
    return False

# Helper function to get all paths of a given length in a graph
def get_paths(graph, length):
    # Initialize a list to store all paths
    paths = []
    # Iterate over all vertices
    for v in range(N):
        # Iterate over all edges
        for edge in graph:
            # If the edge starts at the current vertex, add it to the path
            if edge[0] == v:
                path = [v, edge[1]]
                # Iterate over the remaining edges to build the path
                for _ in range(length - 2):
                    for edge in graph:
                        if edge[0] == path[-1]:
                            path.append(edge[1])
                            break
                paths.append(path)
    return paths

# Helper function to calculate the degree of a vertex in a graph
def degree(graph, v):
    return sum(1 for edge in graph if v in edge)

