from itertools import combinations
import numpy as np

# Generate all possible edges in the complete graph K_9
edges = list(combinations(range(9), 2))

# Initialize the colors of the edges
colors = np.zeros(len(edges), dtype=int)

# Function to check if a clique is monochromatic
def is_monochromatic(clique, colors):
    color = colors[edges.index(clique)]
    for i in range(len(clique)):
        for j in range(i+1, len(clique)):
            edge = tuple(sorted((clique[i], clique[j])))
            if colors[edges.index(edge)] != color:
                return False
    return True

# Function to check if the coloring is valid
def is_valid_coloring(colors):
    # Check for monochromatic red cliques of size 4
    for clique in combinations(range(9), 4):
        if is_monochromatic(clique, colors):
            return False
    # Check for monochromatic blue cliques of size 3
    for clique in combinations(range(9), 3):
        if is_monochromatic(clique, 1-colors):
            return False
    return True

# Try all possible colorings
for coloring in range(2**len(edges)):
    binary_coloring = [int(x) for x in bin(coloring)[2:].zfill(len(edges))]
    if is_valid_coloring(binary_coloring):
        print(binary_coloring)
        break
else:
    print("UNSATISFIABLE")

from itertools import permutations

# Define the size of the grid
n = 4

# Define the block size
block_size = 2

# Define the fixed values
fixed_values = {7: 2, 9: 1, 12: 4}

# Generate all possible permutations of numbers from 1 to n
perms = list(permutations(range(1, n + 1)))

# Initialize an empty solution
solution = None

# Iterate over all permutations
for p in perms:
    # Initialize an empty grid
    grid = [0] * (n * n)

    # Fill the grid with the current permutation
    index = 0
    for i in range(n):
        for j in range(n):
            if index < len(p):
                grid[i * n + j] = p[index]
                index += 1

    # Check if the grid is valid
    valid = True
    for i in range(n):
        # Check rows
        row = [grid[i * n + j] for j in range(n)]
        if sorted(row) != list(range(1, n + 1)):
            valid = False
            break

    for j in range(n):
        # Check columns
        col = [grid[i * n + j] for i in range(n)]
        if sorted(col) != list(range(1, n + 1)):
            valid = False
            break

    for i in range(0, n, block_size):
        for j in range(0, n, block_size):
            # Check blocks
            block = [grid[(i + k) * n + (j + l)] for k in range(block_size) for l in range(block_size)]
            if sorted(block) != list(range(1, n + 1)):
                valid = False
                break
        if not valid:
            break

    # Check if the fixed values are respected
    for pos, val in fixed_values.items():
        if grid[pos] != val:
            valid = False
            break

    # If the grid is valid, store it as the solution
    if valid:
        solution = grid
        break

# If a solution is found, print it
if solution:
    print(solution)
else:
    print("UNSATISFIABLE")

